#!/usr/bin/env python3
"""Fetch a session trace + backoffice and render readable transcript to /tmp/bt/<sid>.txt"""
import json, os, sys, urllib.request

URL = os.environ["ARENA_URL"].rstrip("/")
KEY = os.environ["ARENA_API_KEY"]


def get(path):
    req = urllib.request.Request(URL + path, headers={"X-API-Key": KEY})
    with urllib.request.urlopen(req, timeout=60) as r:
        return json.loads(r.read())


def render(sid):
    s = get(f"/v1/sessions/{sid}")
    try:
        bo = get(f"/v1/sessions/{sid}/backoffice")
    except Exception as e:
        bo = {"error": str(e)}
    out = []
    res = s.get("result") or {}
    out.append(f"SESSION {sid} case={s.get('case_id')} end={s.get('end_reason')} rounds={s.get('rounds')}")
    out.append(f"score={res.get('score')} c_open={res.get('c_open')} c_deal={res.get('c_deal')} c_alt={res.get('c_alt')} supplier={res.get('supplier_id')}")
    out.append(f"terms={json.dumps(res.get('terms'))}")
    out.append(f"breakdown={json.dumps(res.get('cost_breakdown'))}")
    out.append("")
    for t in res.get("trace", []):
        mv = t.get("move", {})
        out.append(f"--- round {t.get('round')} actor={t.get('actor')} status={mv.get('status')} from={mv.get('from')}")
        if mv.get("subject"):
            out.append(f"SUBJECT: {mv.get('subject')}")
        if mv.get("body"):
            out.append(mv["body"])
        ts = mv.get("term_sheets") or []
        for x in ts:
            out.append(f"  TS {x.get('term_sheet_id','')}: {json.dumps(x.get('terms'))}")
        if mv.get("refs"):
            out.append(f"  REFS: {mv['refs']}")
        if mv.get("claim_results"):
            out.append(f"  CLAIMS: {mv['claim_results']}")
        if mv.get("action"):
            out.append(f"  ACTION: {mv['action']}")
        if mv.get("signals"):
            out.append(f"  SIGNALS: {mv['signals']}")
        if t.get("reasons"):
            r = t["reasons"]
            out.append("  REASONS: " + (json.dumps(r, ensure_ascii=False) if not isinstance(r, str) else r))
        out.append("")
    out.append("=== BACKOFFICE ===")
    out.append(json.dumps(bo, indent=1, ensure_ascii=False))
    txt = "\n".join(out)
    open(f"/tmp/bt/{sid}.txt", "w").write(txt)
    json.dump({"session": s, "backoffice": bo}, open(f"/tmp/bt/{sid}.json", "w"))
    return txt


if __name__ == "__main__":
    for sid in sys.argv[1:]:
        render(sid)
        print("wrote", sid)

